window.CIVIL_SET_DATA["past-09"] = {"title":"Past Paper Set 9","negativeMarking":0,"chapters":[{"name":"Basic Civil Engineering","questions":[{"id":"PAST-09-001","src":"PAST-09-001","text":"Plaster of Paris is obtained by the calcination of","options":[{"key":"a","text":"Gypsum"},{"key":"b","text":"Calcium oxide"},{"key":"c","text":"Calcium carbonate"},{"key":"d","text":"Quick lime"}],"answer":"a","explanation":"Heating gypsum (CaSO<sub>4</sub>·2H<sub>2</sub>O) to about 150–160°C drives off part of its water, giving the hemihydrate CaSO<sub>4</sub>·½H<sub>2</sub>O, which is plaster of Paris.","marks":1,"source":{"kind":"past","set":9,"question":1,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q1 · 1 mark"},"topic":"ACiE0101"},{"id":"PAST-09-002","src":"PAST-09-002","text":"The compressive strength of a first class brick is","options":[{"key":"a","text":"&gt;10.5"},{"key":"b","text":"&gt;7"},{"key":"c","text":"&gt;3.5"},{"key":"d","text":"&lt;3.5"}],"answer":"a","explanation":"A first-class brick must have a compressive strength of at least about 10.5 N per mm<sup>2</sup>. Second-class bricks need about 7 N per mm<sup>2</sup>.","marks":1,"source":{"kind":"past","set":9,"question":2,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q2 · 1 mark"},"topic":"ACiE0102"},{"id":"PAST-09-004","src":"PAST-09-004","text":"In which of the following do the CG and geometric centre not coincide?","options":[{"key":"a","text":"Circle"},{"key":"b","text":"Equilateral triangle"},{"key":"c","text":"Rectangle"},{"key":"d","text":"Right angle triangle"}],"answer":"d","explanation":"A circle, a rectangle and an equilateral triangle each have a single natural centre that coincides with the centroid. A right-angled triangle has no such centre: its centroid (one-third in from the legs) differs from, for example, its circumcentre at the midpoint of the hypotenuse.","marks":1,"source":{"kind":"past","set":9,"question":4,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q4 · 1 mark"},"topic":"ACiE0104"},{"id":"PAST-09-019","src":"PAST-09-019","text":"If the level is placed at the mid-point (between two stations), which error is eliminated?","options":[{"key":"a","text":"\\(C_c\\) (curvature)"},{"key":"b","text":"\\(C_r\\) (refraction)"},{"key":"c","text":"Both"},{"key":"d","text":"None"}],"answer":"c","explanation":"With equal backsight and foresight distances, the curvature and refraction corrections, and any collimation error, are the same on both staffs and cancel out.","marks":1,"source":{"kind":"past","set":9,"question":19,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q19 · 1 mark"},"topic":"ACiE0105"},{"id":"PAST-09-029","src":"PAST-09-029","text":"The lowest edge of the sloping surface of a roof is called","options":[{"key":"a","text":"Ridge"},{"key":"b","text":"Rafters"},{"key":"c","text":"Pitch"},{"key":"d","text":"Eaves"}],"answer":"d","explanation":"The eaves are the lower edge of a sloping roof, projecting beyond the wall. The ridge is the apex line, rafters are the sloping members and pitch is the slope.","marks":1,"source":{"kind":"past","set":9,"question":29,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q29 · 1 mark"},"topic":"ACiE0103"},{"id":"PAST-09-062","src":"PAST-09-062","text":"The second moment of area of a triangle about its base is","options":[{"key":"a","text":"\\(I = \\dfrac{bh^3}{36}\\)"},{"key":"b","text":"\\(I = \\dfrac{bh^3}{24}\\)"},{"key":"c","text":"\\(I = \\dfrac{bh^3}{12}\\)"},{"key":"d","text":"\\(I = \\dfrac{bh^3}{6}\\)"}],"answer":"c","explanation":"For a triangle, \\(I\\) about the centroidal axis parallel to the base is \\(\\dfrac{bh^3}{36}\\). Adding \\[A\\left(\\dfrac{h}{3}\\right)^2 = \\dfrac{bh^3}{18}\\] gives \\(\\dfrac{bh^3}{12}\\) about the base.","marks":2,"source":{"kind":"past","set":9,"question":62,"marks":2,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q62 · 2 marks"},"topic":"ACiE0104"},{"id":"PAST-09-063","src":"PAST-09-063","text":"The section modulus of a hollow circular section is","options":[{"key":"a","text":"\\(Z = \\dfrac{\\pi(D^5 - d^4)}{30D}\\)"},{"key":"b","text":"\\(Z = \\dfrac{\\pi(D^4 - d^4)}{32D}\\)"},{"key":"c","text":"\\(Z = \\dfrac{\\pi(D^4 - d^4)}{16D}\\)"},{"key":"d","text":"\\(Z = \\dfrac{\\pi(D^2 - d^2)}{32D}\\)"}],"answer":"b","explanation":"The section modulus is \\[\\begin{aligned} Z &amp;= \\dfrac{I}{y_{max}} \\\\ &amp;= \\dfrac{\\pi(D^4 - d^4)}{64} \\times \\dfrac{2}{D} \\\\ &amp;= \\dfrac{\\pi(D^4 - d^4)}{32D} \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":9,"question":63,"marks":2,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q63 · 2 marks"},"topic":"ACiE0104"}]},{"name":"Soil Mechanics and Foundation Engineering","questions":[{"id":"PAST-09-003","src":"PAST-09-003","text":"The oedometer is used for","options":[{"key":"a","text":"Consolidation"},{"key":"b","text":"Compaction"},{"key":"c","text":"Permeability"},{"key":"d","text":"Void ratio"}],"answer":"a","explanation":"The oedometer (consolidometer) loads a laterally confined specimen in stages to find the e–log p curve, the compression index and the coefficient of consolidation.","marks":1,"source":{"kind":"past","set":9,"question":3,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q3 · 1 mark"},"topic":"ACiE0206"},{"id":"PAST-09-010","src":"PAST-09-010","text":"What is the relation for active earth pressure in a cohesive soil?","options":[{"key":"a","text":"\\(K_a\\sigma_z - 2C\\sqrt{K_a}\\)"},{"key":"b","text":"\\(K_a\\sigma_z + 2C\\sqrt{K_a}\\)"},{"key":"c","text":"\\(K_a\\sigma_z - C\\sqrt{K_a}\\)"},{"key":"d","text":"\\(K_a\\sigma_z + C\\sqrt{K_a}\\)"}],"answer":"a","explanation":"Bell's extension of Rankine's theory gives \\[p_a = K_a\\sigma_z - 2c\\sqrt{K_a}\\] which is negative (tension) near the top down to \\(z_c = \\dfrac{2c}{\\gamma\\sqrt{K_a}}\\).","marks":1,"source":{"kind":"past","set":9,"question":10,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q10 · 1 mark"},"topic":"ACiE0204"},{"id":"PAST-09-011","src":"PAST-09-011","text":"What would be the effect on effective stress if the water table is above the GL?","options":[{"key":"a","text":"Decreases"},{"key":"b","text":"Increases"},{"key":"c","text":"Remains constant"},{"key":"d","text":"Cannot be said exactly"}],"answer":"c","explanation":"Standing water above the ground adds equally to the total stress and the pore pressure at every depth, so the effective stress in the soil (γ′z) does not change.","marks":1,"source":{"kind":"past","set":9,"question":11,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q11 · 1 mark"},"topic":"ACiE0202"},{"id":"PAST-09-014","src":"PAST-09-014","text":"The shear strength of a plastic undrained clay depends upon","options":[{"key":"a","text":"internal friction"},{"key":"b","text":"cohesion"},{"key":"c","text":"internal friction and cohesion"},{"key":"d","text":"unit weight of clay"}],"answer":"b","explanation":"In undrained loading of a saturated clay \\(\\phi_u = 0\\), so the strength is the undrained cohesion \\(c_u\\) alone.","marks":1,"source":{"kind":"past","set":9,"question":14,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q14 · 1 mark"},"topic":"ACiE0203"},{"id":"PAST-09-015","src":"PAST-09-015","text":"When two column loads are unequal, which of the following footings can be provided?","options":[{"key":"a","text":"Strap footing"},{"key":"b","text":"Raft footing"},{"key":"c","text":"Trapezoidal combined footing"},{"key":"d","text":"Mat footing"}],"answer":"c","explanation":"A trapezoidal combined footing, wider under the heavier column, puts the centroid of the base under the resultant load and gives uniform soil pressure. It suits unequal loads, especially when space beyond the heavier column is limited.","marks":1,"source":{"kind":"past","set":9,"question":15,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q15 · 1 mark"},"topic":"ACiE0205"},{"id":"PAST-09-016","src":"PAST-09-016","text":"The weight of capillary water is held by","options":[{"key":"a","text":"shear force"},{"key":"b","text":"cohesion"},{"key":"c","text":"surface tension"},{"key":"d","text":"molecular forces"}],"answer":"c","explanation":"Capillary water is lifted and held above the water table by surface tension acting at the curved menisci in the soil pores.","marks":1,"source":{"kind":"past","set":9,"question":16,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q16 · 1 mark"},"topic":"ACiE0201"},{"id":"PAST-09-038","src":"PAST-09-038","text":"The coefficient of subgrade reaction doesn't depend upon","options":[{"key":"a","text":"the size of footing"},{"key":"b","text":"the shape of footing"},{"key":"c","text":"the depth of footing"},{"key":"d","text":"the water table"}],"answer":"d","explanation":"The modulus of subgrade reaction \\(k = \\dfrac{p}{\\delta}\\) varies with the soil type and with the size, shape and depth of the loaded area. The key treats the water table as the factor it does not depend on.","marks":1,"source":{"kind":"past","set":9,"question":38,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q38 · 1 mark"},"topic":"ACiE0206"},{"id":"PAST-09-055","src":"PAST-09-055","text":"The maximum permissible eccentricity of a retaining wall of base width 'B' to avoid failure in tension is","options":[{"key":"a","text":"B/2"},{"key":"b","text":"B/3"},{"key":"c","text":"B/6"},{"key":"d","text":"B/12"}],"answer":"c","explanation":"No tension develops under the base while the resultant lies within the middle third, i.e. e ≤ B/6.","marks":1,"source":{"kind":"past","set":9,"question":55,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q55 · 1 mark"},"topic":"ACiE0204"},{"id":"PAST-09-058","src":"PAST-09-058","text":"The coefficient of compressibility of soil is the ratio of","options":[{"key":"a","text":"stress to strain"},{"key":"b","text":"strain to stress"},{"key":"c","text":"stress to settlement"},{"key":"d","text":"rate of loading to that of settlement"}],"answer":"b","explanation":"The coefficient of compressibility is the decrease in void ratio (a strain measure) per unit increase in effective stress: \\[a_v = -\\dfrac{\\Delta e}{\\Delta\\sigma'}\\] \\[m_v = \\dfrac{a_v}{1 + e_0}\\]","marks":1,"source":{"kind":"past","set":9,"question":58,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q58 · 1 mark"},"topic":"ACiE0206"},{"id":"PAST-09-060","src":"PAST-09-060","text":"The formula for the ultimate bearing capacity of a square footing is","options":[{"key":"a","text":"\\(Q_\\mathrm{ult} = cN_c\\) \\(+\\,qN_q\\) \\(+\\,0.5B\\gamma N_\\gamma\\)"},{"key":"b","text":"\\(Q_\\mathrm{ult} = cN_c\\) \\(+\\,qN_q\\) \\(+\\,0.4B\\gamma N_\\gamma\\)"},{"key":"c","text":"\\(Q_\\mathrm{ult} = 1.3cN_c\\) \\(+\\,qN_q\\) \\(+\\,0.3B\\gamma N_\\gamma\\)"},{"key":"d","text":"\\(Q_\\mathrm{ult} = 1.3cN_c\\) \\(+\\,qN_q\\) \\(+\\,0.4B\\gamma N_\\gamma\\)"}],"answer":"d","explanation":"Terzaghi's square footing: \\[\\begin{aligned} q_u &amp;= 1.3cN_c + qN_q \\\\ &amp;\\quad + 0.4\\gamma BN_\\gamma \\end{aligned}\\] The strip footing uses \\(c\\), \\(q\\), 0.5 and the circular footing 1.3, \\(q\\), 0.3.","marks":1,"source":{"kind":"past","set":9,"question":60,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q60 · 1 mark"},"topic":"ACiE0206"},{"id":"PAST-09-076","src":"PAST-09-076","text":"The falling head permeability test can be used for","options":[{"key":"a","text":"coarse-grained soil"},{"key":"b","text":"less permeable soil"},{"key":"c","text":"clayey soil"},{"key":"d","text":"all of the mentioned"}],"answer":"b","explanation":"The falling (variable) head test measures the small flows through relatively less permeable soils such as fine sands and silts. The constant head test suits coarse, highly permeable soils.","marks":2,"source":{"kind":"past","set":9,"question":76,"marks":2,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q76 · 2 marks"},"topic":"ACiE0201"},{"id":"PAST-09-077","src":"PAST-09-077","text":"The (safe) bearing capacity of soft rocks is","options":[{"key":"a","text":"440 kN/m<sup>2</sup>"},{"key":"b","text":"880 kN/m<sup>2</sup>"},{"key":"c","text":"1620 kN/m<sup>2</sup>"},{"key":"d","text":"3240 kN/m<sup>2</sup>"}],"answer":"a","explanation":"IS 1904 gives the safe bearing capacity of soft rock as 440 kN per m<sup>2</sup>. Hard shale and broken bedrock allow 880, laminated rock 1620 and hard sound rock 3240 kN per m<sup>2</sup>.","marks":2,"source":{"kind":"past","set":9,"question":77,"marks":2,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q77 · 2 marks"},"topic":"ACiE0206"}]},{"name":"Basic Water Resources Engineering","questions":[{"id":"PAST-09-007","src":"PAST-09-007","text":"What is the formula for sequent depth?","options":[{"key":"a","text":"\\(\\dfrac{y_2}{y_1} ={}\\) \\(0.5\\left(\\sqrt{8F^2+1} - 1\\right)\\)"},{"key":"b","text":"\\(\\dfrac{y_2}{y_1} ={}\\) \\(0.5\\sqrt{8F^2+1} - 1\\)"},{"key":"c","text":"\\(\\dfrac{y_2}{y_1} ={}\\) \\(\\sqrt{8F^2+1} - 1\\)"},{"key":"d","text":"\\(\\dfrac{y_2}{y_1} ={}\\) \\(\\sqrt{8F^2+1} + 1\\)"}],"answer":"a","explanation":"For a hydraulic jump in a rectangular channel, the Bélanger equation gives \\[\\dfrac{y_2}{y_1} = \\dfrac{1}{2}\\left[\\sqrt{1 + 8F_1^2} - 1\\right]\\]","marks":1,"source":{"kind":"past","set":9,"question":7,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q7 · 1 mark"},"topic":"ACiE0305"},{"id":"PAST-09-012","src":"PAST-09-012","text":"What will be the effect on the probability of annual damage if the design flood is increased?","options":[{"key":"a","text":"Decreases"},{"key":"b","text":"Increases"},{"key":"c","text":"Remains constant"},{"key":"d","text":"Depends on location"}],"answer":"a","explanation":"A larger design flood has a longer return period T, so the annual probability of it being exceeded, 1/T, falls and damage becomes less likely in any year.","marks":1,"source":{"kind":"past","set":9,"question":12,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q12 · 1 mark"},"topic":"ACiE0306"},{"id":"PAST-09-023","src":"PAST-09-023","text":"In Bernoulli's equation each term represents","options":[{"key":"a","text":"total energy per unit mass"},{"key":"b","text":"total energy per unit volume"},{"key":"c","text":"total energy per unit weight"},{"key":"d","text":"total energy per unit flow area"}],"answer":"c","explanation":"In the form \\[\\dfrac{p}{\\gamma} + \\dfrac{V^2}{2g} + z = \\text{constant}\\] each term is a head in metres, i.e. energy per unit weight of fluid.","marks":1,"source":{"kind":"past","set":9,"question":23,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q23 · 1 mark"},"topic":"ACiE0303"},{"id":"PAST-09-028","src":"PAST-09-028","text":"The Froude number value for a steady jump is","options":[{"key":"a","text":"1.7–2.5"},{"key":"b","text":"2.5–4.5"},{"key":"c","text":"4.5–9"},{"key":"d","text":"&gt;9"}],"answer":"c","explanation":"Jumps are classed by the approach Froude number: undular 1–1.7, weak 1.7–2.5, oscillating 2.5–4.5, steady 4.5–9 and strong above 9. The steady jump is well formed and dissipates 45–70% of the energy.","marks":1,"source":{"kind":"past","set":9,"question":28,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q28 · 1 mark"},"topic":"ACiE0305"},{"id":"PAST-09-036","src":"PAST-09-036","text":"Prandtl's mixing length is","options":[{"key":"a","text":"a universal constant"},{"key":"b","text":"zero at the pipe wall"},{"key":"c","text":"independent of shear stress"},{"key":"d","text":"independent of radial distance from the pipe axis"}],"answer":"b","explanation":"The mixing length varies with distance from the wall (\\(l = \\kappa y\\) near it, \\(\\kappa \\approx 0.4\\)), so it is zero at the wall itself, where turbulent mixing vanishes.","marks":1,"source":{"kind":"past","set":9,"question":36,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q36 · 1 mark"},"topic":"ACiE0304"},{"id":"PAST-09-042","src":"PAST-09-042","text":"The rise of a liquid in a capillary tube depends on","options":[{"key":"a","text":"the material"},{"key":"b","text":"the length"},{"key":"c","text":"the outer radius"},{"key":"d","text":"the inner radius of the tube"}],"answer":"d","explanation":"The capillary rise is \\[h = \\dfrac{2\\sigma\\cos\\theta}{\\rho gr}\\] where \\(r\\) is the inner (bore) radius, so the rise is inversely proportional to it. The tube's length and outer radius have no effect.","marks":1,"source":{"kind":"past","set":9,"question":42,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q42 · 1 mark"},"topic":"ACiE0301"},{"id":"PAST-09-064","src":"PAST-09-064","text":"Match the following: A. Capillarity, B. Vapour pressure, C. Viscosity, D. Specific gravity with a. Cavitation, b. Density of water, c. Shear forces, d. Surface tension.","options":[{"key":"a","text":"A-a, B-d, C-b, D-c"},{"key":"b","text":"A-a, B-d, C-c, D-b"},{"key":"c","text":"A-d, B-a, C-b, D-c"},{"key":"d","text":"A-d, B-a, C-c, D-b"}],"answer":"d","explanation":"Capillarity comes from surface tension, and cavitation occurs when pressure falls to the vapour pressure. Viscosity resists shear forces, and specific gravity compares a density with that of water.","marks":2,"source":{"kind":"past","set":9,"question":64,"marks":2,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q64 · 2 marks"},"topic":"ACiE0301"},{"id":"PAST-09-065","src":"PAST-09-065","text":"The sequent depth ratio of a hydraulic jump in a rectangular channel is 16.48. What is the Froude number (approximately) at the beginning of the jump?","options":[{"key":"a","text":"5"},{"key":"b","text":"9"},{"key":"c","text":"8"},{"key":"d","text":"12"}],"answer":"d","explanation":"From \\[\\dfrac{1}{2}\\left[\\sqrt{1 + 8F^2} - 1\\right] = 16.48\\] \\(\\sqrt{1 + 8F^2} = 33.96\\), so \\(F^2 \\approx 144\\) and \\(F \\approx 12\\).","marks":2,"source":{"kind":"past","set":9,"question":65,"marks":2,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q65 · 2 marks"},"topic":"ACiE0305"},{"id":"PAST-09-071","src":"PAST-09-071","text":"If Manning's n is doubled, then the slope should be changed to","options":[{"key":"a","text":"halved"},{"key":"b","text":"doubled"},{"key":"c","text":"one-quarter"},{"key":"d","text":"quadruple"}],"answer":"d","explanation":"Manning's equation is \\[V = \\dfrac{1}{n}R^{2{/}3}S^{1{/}2}\\] so keeping the same velocity with double \\(n\\) needs \\(\\sqrt{S}\\) doubled, i.e. \\(S\\) made four times.","marks":2,"source":{"kind":"past","set":9,"question":71,"marks":2,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q71 · 2 marks"},"topic":"ACiE0305"}]},{"name":"Structural Mechanics","questions":[{"id":"PAST-09-013","src":"PAST-09-013","text":"In influence line diagrams (ILD)","options":[{"key":"a","text":"points remain fixed, position of load changes"},{"key":"b","text":"points change, position of loads remains fixed"},{"key":"c","text":"both of them change"},{"key":"d","text":"neither of them changes"}],"answer":"a","explanation":"An influence line gives a response at one fixed section as a unit load travels across the span.<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-05-053-what-an-influence-line-shows.svg' target='_blank' rel='noopener noreferrer' aria-label='Open An influence line: the section stays fixed while the load moves'><img src='assets/civil-past-solutions/past-05-053-what-an-influence-line-shows.svg' width='720' height='420' loading='lazy' decoding='async' alt='An influence line gives one response, here the moment at a fixed section C, as a unit load moves across the span. Each ordinate is the value at C when the unit load stands directly above that point.'></a><figcaption>An influence line: the section stays fixed while the load moves</figcaption></figure>","marks":1,"source":{"kind":"past","set":9,"question":13,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q13 · 1 mark"},"topic":"ACiE0404"},{"id":"PAST-09-030","src":"PAST-09-030","text":"The locus of the reaction of a two hinged semicircular arch is","options":[{"key":"a","text":"a straight line"},{"key":"b","text":"a parabola"},{"key":"c","text":"a circle"},{"key":"d","text":"a hyperbola"}],"answer":"a","explanation":"For a unit load moving over a two-hinged semicircular arch, the reactions at both springings intersect on a horizontal straight line at a height πR/2 above the springings.<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-09-030-reaction-locus-of-a-semicircular-arch.svg' target='_blank' rel='noopener noreferrer' aria-label='Open Where the reactions of a two-hinged semicircular arch meet'><img src='assets/civil-past-solutions/past-09-030-reaction-locus-of-a-semicircular-arch.svg' width='720' height='420' loading='lazy' decoding='async' alt='For any position of a point load on a two-hinged semicircular arch, the two support reactions meet on the load line at a height πR/2 above the springings. As the load moves, this meeting point traces a horizontal straight line.'></a><figcaption>Where the reactions of a two-hinged semicircular arch meet</figcaption></figure>","marks":1,"source":{"kind":"past","set":9,"question":30,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q30 · 1 mark"},"topic":"ACiE0406"},{"id":"PAST-09-035","src":"PAST-09-035","text":"An abrupt change in the bending moment diagram occurs if a …… is applied.","options":[{"key":"a","text":"Couple"},{"key":"b","text":"Impact load"},{"key":"c","text":"Shear force"},{"key":"d","text":"Axial force"}],"answer":"a","explanation":"A concentrated couple produces a sudden jump in the BMD equal to its magnitude. A concentrated force causes a jump in the SFD instead.<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-09-035-couple-makes-the-moment-jump.svg' target='_blank' rel='noopener noreferrer' aria-label='Open A point load steps the SFD; a couple steps the BMD'><img src='assets/civil-past-solutions/past-09-035-couple-makes-the-moment-jump.svg' width='720' height='420' loading='lazy' decoding='async' alt='A concentrated force causes a sudden jump in the shear force diagram and only a kink in the moment diagram. A concentrated couple leaves the shear unchanged and makes the moment jump by its own value.'></a><figcaption>A point load steps the SFD; a couple steps the BMD</figcaption></figure>","marks":1,"source":{"kind":"past","set":9,"question":35,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q35 · 1 mark"},"topic":"ACiE0401"},{"id":"PAST-09-040","src":"PAST-09-040","text":"The shear stress at the edge (outer surface) of a shaft in torsion is","options":[{"key":"a","text":"Maximum"},{"key":"b","text":"Minimum"},{"key":"c","text":"Zero"},{"key":"d","text":"Negative"}],"answer":"a","explanation":"Torsional shear stress \\[\\tau = \\dfrac{Tr}{J}\\] grows linearly from zero at the axis to its maximum at the outer surface.<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-09-040-torsional-shear-peaks-at-the-surface.svg' target='_blank' rel='noopener noreferrer' aria-label='Open Torsional shear stress grows from the centre to the surface'><img src='assets/civil-past-solutions/past-09-040-torsional-shear-peaks-at-the-surface.svg' width='720' height='420' loading='lazy' decoding='async' alt='In a shaft under torque T the shear stress is τ = Tr/J: zero on the axis and growing linearly with the radius to its largest value TR/J at the outer surface.'></a><figcaption>Torsional shear stress grows from the centre to the surface</figcaption></figure>","marks":1,"source":{"kind":"past","set":9,"question":40,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q40 · 1 mark"},"topic":"ACiE0403"},{"id":"PAST-09-057","src":"PAST-09-057","text":"\\(m_1\\) and \\(m_2\\) are the numbers of members of two individual trusses of a combined truss. The compound truss will be determinate if","options":[{"key":"a","text":"\\(m = m_1 + m_2\\)"},{"key":"b","text":"\\(m = m_1 + m_2 + 1\\)"},{"key":"c","text":"\\(m = m_1 + m_2 + 2\\)"},{"key":"d","text":"\\(m = m_1 + m_2 + 3\\)"}],"answer":"d","explanation":"Two simple rigid trusses are joined rigidly by three bars that are neither parallel nor concurrent, so a determinate compound truss has \\[m = m_1 + m_2 + 3\\]<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-09-057-joining-two-simple-trusses.svg' target='_blank' rel='noopener noreferrer' aria-label='Open Joining two simple trusses into a determinate compound truss'><img src='assets/civil-past-solutions/past-09-057-joining-two-simple-trusses.svg' width='720' height='420' loading='lazy' decoding='async' alt='Each simple truss is rigid with m = 2j - 3. Three bars that are neither parallel nor concurrent fix one truss to the other, like the three reactions of a rigid body, so the compound truss is rigid and determinate with m = m1 + m2 + 3.'></a><figcaption>Joining two simple trusses into a determinate compound truss</figcaption></figure>","marks":1,"source":{"kind":"past","set":9,"question":57,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q57 · 1 mark"},"topic":"ACiE0405"},{"id":"PAST-09-066","src":"PAST-09-066","text":"If the shear force along a section of a beam is zero, the bending moment at the section is","options":[{"key":"a","text":"zero"},{"key":"b","text":"maximum"},{"key":"c","text":"minimum"},{"key":"d","text":"average of maximum-minimum"}],"answer":"b","explanation":"Since \\(\\dfrac{dM}{dx} = S\\), the bending moment has a stationary value where the shear force is zero or changes sign. This is the section of maximum bending moment.<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-09-066-zero-shear-maximum-moment.svg' target='_blank' rel='noopener noreferrer' aria-label='Open Where the shear is zero the moment is greatest'><img src='assets/civil-past-solutions/past-09-066-zero-shear-maximum-moment.svg' width='720' height='420' loading='lazy' decoding='async' alt='For a simply supported beam under a uniform load, the shear falls from wL/2 to -wL/2 and passes through zero at mid-span. There dM/dx = 0, and the moment reaches its maximum wL squared/8.'></a><figcaption>Where the shear is zero the moment is greatest</figcaption></figure>","marks":2,"source":{"kind":"past","set":9,"question":66,"marks":2,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q66 · 2 marks"},"topic":"ACiE0401"},{"id":"PAST-09-067","src":"PAST-09-067","text":"The effective length used in the crippling load formula for a column with both ends fixed is","options":[{"key":"a","text":"\\(\\dfrac{L}{2}\\)"},{"key":"b","text":"\\(L\\)"},{"key":"c","text":"\\(2L\\)"},{"key":"d","text":"\\(\\dfrac{L}{\\sqrt{2}}\\)"}],"answer":"a","explanation":"Fixing both ends halves the buckling length, \\(l_e = \\dfrac{L}{2}\\) (theoretical), so \\[P = \\dfrac{4\\pi^2EI}{L^2}\\]<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-09-067-effective-length-fixed-both-ends.svg' target='_blank' rel='noopener noreferrer' aria-label='Open Effective length of a column fixed at both ends'><img src='assets/civil-past-solutions/past-09-067-effective-length-fixed-both-ends.svg' width='720' height='420' loading='lazy' decoding='async' alt='Fixing both ends puts points of contraflexure L/4 from each end, so the length that buckles like a pin-ended column is L/2. The theoretical effective length is L/2; design codes recommend 0.65L.'></a><figcaption>Effective length of a column fixed at both ends</figcaption></figure>","marks":2,"source":{"kind":"past","set":9,"question":67,"marks":2,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q67 · 2 marks"},"topic":"ACiE0403"}]},{"name":"Design of Structures","questions":[{"id":"PAST-09-005","src":"PAST-09-005","text":"Which of the following is important while designing a (simply supported) beam?","options":[{"key":"a","text":"SF at support"},{"key":"b","text":"BM at support"},{"key":"c","text":"SF at centre"},{"key":"d","text":"BM at centre"}],"answer":"d","explanation":"A simply supported beam is designed chiefly for the maximum bending moment, which occurs at or near midspan. Shear governs the stirrups near the supports.<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-09-005-design-moment-at-midspan.svg' target='_blank' rel='noopener noreferrer' aria-label='Open Shear and moment in a simply supported beam under a uniform load'><img src='assets/civil-past-solutions/past-09-005-design-moment-at-midspan.svg' width='720' height='420' loading='lazy' decoding='async' alt='A simply supported beam under a uniform load has its largest bending moment, wL squared/8, at midspan, and this governs the section and the main steel. The shear is largest, wL/2, at the supports and governs the stirrups there.'></a><figcaption>Shear and moment in a simply supported beam under a uniform load</figcaption></figure>","marks":1,"source":{"kind":"past","set":9,"question":5,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q5 · 1 mark"},"topic":"ACiE0503"},{"id":"PAST-09-025","src":"PAST-09-025","text":"The applicability of the middle third rule used in the design of structures under combined direct and bending stresses is","options":[{"key":"a","text":"feasible to circular cross sections only"},{"key":"b","text":"feasible to square and circular cross sections only"},{"key":"c","text":"feasible to rectangular cross-sections only"},{"key":"d","text":"feasible to all cross sections"}],"answer":"c","explanation":"The middle-third rule (e ≤ b/6 for no tension) is derived for rectangular sections. A circular section has a middle-quarter kern (e ≤ d/8).<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-09-025-kern-of-rectangle-and-circle.svg' target='_blank' rel='noopener noreferrer' aria-label='Open Kern of a rectangle (middle third) and of a circle (middle quarter)'><img src='assets/civil-past-solutions/past-09-025-kern-of-rectangle-and-circle.svg' width='720' height='420' loading='lazy' decoding='async' alt='A load inside the kern causes no tension anywhere on the section. For a rectangle the kern is a rhombus reaching b/6 each side of the centre, the middle third. For a circle it is a circle of diameter d/4, the middle quarter, so the middle-third rule holds only for rectangular sections.'></a><figcaption>Kern of a rectangle (middle third) and of a circle (middle quarter)</figcaption></figure>","marks":1,"source":{"kind":"past","set":9,"question":25,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q25 · 1 mark"},"topic":"ACiE0506"},{"id":"PAST-09-041","src":"PAST-09-041","text":"Which of the following is not a dead load?","options":[{"key":"a","text":"Partition wall"},{"key":"b","text":"Students in class"},{"key":"c","text":"Floor finish"},{"key":"d","text":"Furniture in class"}],"answer":"b","explanation":"Occupants (students) are imposed (live) load, varying in amount and position. Walls, partitions and floor finishes are permanent dead loads. Movable furniture is also normally treated as imposed load; the key's intended answer is the students.","marks":1,"source":{"kind":"past","set":9,"question":41,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q41 · 1 mark"},"topic":"ACiE0501"},{"id":"PAST-09-043","src":"PAST-09-043","text":"The relationship between flexural strength and characteristic strength is","options":[{"key":"a","text":"\\(f_{cr} = 0.35\\sqrt{f_{ck}}\\)"},{"key":"b","text":"\\(f_{cr} = 0.5\\sqrt{f_{ck}}\\)"},{"key":"c","text":"\\(f_{cr} = 0.7\\sqrt{f_{ck}}\\)"},{"key":"d","text":"\\(f_{cr} = 0.8\\sqrt{f_{ck}}\\)"}],"answer":"c","explanation":"IS 456 gives the flexural strength (modulus of rupture) of concrete, in N per mm<sup>2</sup>, as \\[f_{cr} = 0.7\\sqrt{f_{ck}}\\]","marks":1,"source":{"kind":"past","set":9,"question":43,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q43 · 1 mark"},"topic":"ACiE0502"},{"id":"PAST-09-061","src":"PAST-09-061","text":"For repetitive use of formwork in concrete construction, which material is preferred?","options":[{"key":"a","text":"Stone"},{"key":"b","text":"Steel"},{"key":"c","text":"Timber"},{"key":"d","text":"Bamboo"}],"answer":"b","explanation":"Steel formwork can be reused many times (100+), gives a smooth finish and keeps its shape, so it is economical for repetitive work despite its higher first cost.","marks":2,"source":{"kind":"past","set":9,"question":61,"marks":2,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q61 · 2 marks"},"topic":"ACiE0502"},{"id":"PAST-09-073","src":"PAST-09-073","text":"For an I-beam, the shape factor is 1.12 and the factor of safety in bending is 1.5. If the allowable stress is increased by 20% for wind and earthquake loads, then the load factor is","options":[{"key":"a","text":"1.10"},{"key":"b","text":"1.25"},{"key":"c","text":"1.35"},{"key":"d","text":"1.40"}],"answer":"d","explanation":"The load factor is the shape factor times the FOS. With the allowable stress raised by 20%, the effective FOS becomes \\(\\dfrac{1.5}{1.2} = 1.25\\), so \\[\\text{LF} = 1.12 \\times 1.25 = 1.40\\]<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-09-073-load-factor-with-wind.svg' target='_blank' rel='noopener noreferrer' aria-label='Open Load factor of an I-beam with the allowable stress raised for wind'><img src='assets/civil-past-solutions/past-09-073-load-factor-with-wind.svg' width='720' height='420' loading='lazy' decoding='async' alt='The load factor is the plastic moment divided by the working moment. Raising the allowable stress by 20 percent cuts the factor of safety to 1.5/1.2 = 1.25 between the working moment and first yield, and the shape factor 1.12 takes it on to Mp: LF = 1.12 x 1.25 = 1.40.'></a><figcaption>Load factor of an I-beam with the allowable stress raised for wind</figcaption></figure>","marks":2,"source":{"kind":"past","set":9,"question":73,"marks":2,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q73 · 2 marks"},"topic":"ACiE0505"},{"id":"PAST-09-078","src":"PAST-09-078","text":"The aggregate impact value of the aggregate used in","options":[{"key":"a","text":"building concrete is less than 45"},{"key":"b","text":"road pavement concrete is less than 30"},{"key":"c","text":"runway concrete is less than 30"},{"key":"d","text":"All the options are correct"}],"answer":"d","explanation":"IS 383 limits the aggregate impact value to 45% for general concrete and 30% for wearing surfaces such as roads and runways, so all three statements hold.","marks":2,"source":{"kind":"past","set":9,"question":78,"marks":2,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q78 · 2 marks"},"topic":"ACiE0502"},{"id":"PAST-09-080","src":"PAST-09-080","text":"If the basic wind speed = 55 m/s and \\(k_1\\), \\(k_2\\), \\(k_3\\) are all 1, then the wind pressure considered is","options":[{"key":"a","text":"18.15 N/m<sup>2</sup>"},{"key":"b","text":"181.5 N/m<sup>2</sup>"},{"key":"c","text":"1815 N/m<sup>2</sup>"},{"key":"d","text":"18150 N/m<sup>2</sup>"}],"answer":"c","explanation":"The design wind speed is \\(V_z = V_bk_1k_2k_3 = 55\\) m per s, so \\[\\begin{aligned} p_z &amp;= 0.6V_z^2 = 0.6 \\times 55^2 \\\\ &amp;= 1815 \\end{aligned}\\] N per m<sup>2</sup>.<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-09-080-design-wind-pressure.svg' target='_blank' rel='noopener noreferrer' aria-label='Open Design wind pressure from a basic wind speed of 55 m/s'><img src='assets/civil-past-solutions/past-09-080-design-wind-pressure.svg' width='720' height='420' loading='lazy' decoding='async' alt='With k1 = k2 = k3 = 1 the design wind speed equals the basic speed, Vz = 55 m/s. The design wind pressure is pz = 0.6 Vz squared = 0.6 x 55 squared = 1815 N/m squared.'></a><figcaption>Design wind pressure from a basic wind speed of 55 m/s</figcaption></figure>","marks":2,"source":{"kind":"past","set":9,"question":80,"marks":2,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q80 · 2 marks"},"topic":"ACiE0501"}]},{"name":"Water Supply, Sanitation and Environment","questions":[{"id":"PAST-09-017","src":"PAST-09-017","text":"What would be the effect on pH if bleaching powder is added?","options":[{"key":"a","text":"Decreases"},{"key":"b","text":"Increases"},{"key":"c","text":"Remains constant"},{"key":"d","text":"Depends on initial pH"}],"answer":"b","explanation":"Bleaching powder (calcium hypochlorite) releases \\(\\text{OCl}^-\\) and Ca(OH)<sub>2</sub>, both alkaline, so it raises the pH of water. Chlorine gas lowers it.","marks":1,"source":{"kind":"past","set":9,"question":17,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q17 · 1 mark"},"topic":"ACiE0603"},{"id":"PAST-09-034","src":"PAST-09-034","text":"A submerged intake is located at the","options":[{"key":"a","text":"bottom of river"},{"key":"b","text":"front of river"},{"key":"c","text":"side of river"},{"key":"d","text":"u/s of river"}],"answer":"a","explanation":"A submerged intake is built on the bed of the river or lake, with its inlet below the water surface. It is common for small supplies where the source always has enough depth.","marks":1,"source":{"kind":"past","set":9,"question":34,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q34 · 1 mark"},"topic":"ACiE0602"},{"id":"PAST-09-046","src":"PAST-09-046","text":"If a circular sewer is partially full and the depth is increased, then","options":[{"key":"a","text":"wetted perimeter increases"},{"key":"b","text":"discharge increases"},{"key":"c","text":"velocity decreases"},{"key":"d","text":"All"}],"answer":"a","explanation":"The wetted perimeter always grows with depth. Discharge rises only up to about 0.94D, and velocity actually increases up to about 0.81D before falling, so 'All' is not generally true. The source key gives (d).","marks":1,"source":{"kind":"past","set":9,"question":46,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q46 · 1 mark"},"topic":"ACiE0604"},{"id":"PAST-09-051","src":"PAST-09-051","text":"Which method of population forecasting is used for water supply of a large and old town?","options":[{"key":"a","text":"Arithmetical increase method"},{"key":"b","text":"Geometric progression method"},{"key":"c","text":"Graphical method"},{"key":"d","text":"Logistic curve method"}],"answer":"a","explanation":"Large, old, well-developed towns grow at a roughly constant absolute rate, which suits the arithmetical increase method. Geometric increase suits young, rapidly growing towns.","marks":1,"source":{"kind":"past","set":9,"question":51,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q51 · 1 mark"},"topic":"ACiE0601"},{"id":"PAST-09-052","src":"PAST-09-052","text":"Bacteria that grow best at high temperature (40 to 70°C) are called","options":[{"key":"a","text":"Mesophilic"},{"key":"b","text":"Thermophilic"},{"key":"c","text":"Hyper thermophilic"},{"key":"d","text":"Psychrophilic"}],"answer":"b","explanation":"Thermophiles thrive at about 45–70°C. Mesophiles grow at about 20–45°C and psychrophiles below about 20°C.","marks":1,"source":{"kind":"past","set":9,"question":52,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q52 · 1 mark"},"topic":"ACiE0605"},{"id":"PAST-09-053","src":"PAST-09-053","text":"Which one among the following is the correct order of steps taken during the process of Environmental Impact Assessment (EIA)?","options":[{"key":"a","text":"Scoping, Screening, Public Hearing, EIA, Issue of Environmental Clearance"},{"key":"b","text":"Screening, Public Hearing, Scoping, EIA, Issue of Environmental Clearance"},{"key":"c","text":"Screening, Scoping, EIA, Public Hearing, Issue of Environmental Clearance"},{"key":"d","text":"Screening, EIA, Scoping, Public Hearing, Issue of Environmental Clearance"}],"answer":"c","explanation":"Screening decides whether an EIA is needed, and scoping fixes its issues and ToR. The EIA study and report follow, then the public hearing, review and finally the environmental clearance (approval).","marks":1,"source":{"kind":"past","set":9,"question":53,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q53 · 1 mark"},"topic":"ACiE0606"}]},{"name":"Irrigation and Drainage","questions":[{"id":"PAST-09-006","src":"PAST-09-006","text":"What is the value of Lacey's silt factor f if the diameter of the particle is 2 mm?","options":[{"key":"a","text":"1"},{"key":"b","text":"1.5"},{"key":"c","text":"1.67"},{"key":"d","text":"2.5"}],"answer":"d","explanation":"With \\(d\\) in mm, \\[\\begin{aligned} f &amp;= 1.76\\sqrt{d} = 1.76\\sqrt{2} \\\\ &amp;\\approx 2.49 \\approx 2.5 \\end{aligned}\\]","marks":1,"source":{"kind":"past","set":9,"question":6,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q6 · 1 mark"},"topic":"ACiE0702"},{"id":"PAST-09-026","src":"PAST-09-026","text":"What is the main function of a weir and barrage?","options":[{"key":"a","text":"To increase water height"},{"key":"b","text":"To protect bank"},{"key":"c","text":"To control rainfall"},{"key":"d","text":"None"}],"answer":"a","explanation":"A weir or barrage raises the river level upstream so that water can be diverted into the off-taking canal at the required head.","marks":1,"source":{"kind":"past","set":9,"question":26,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q26 · 1 mark"},"topic":"ACiE0703"},{"id":"PAST-09-027","src":"PAST-09-027","text":"Cross regulators are provided","options":[{"key":"a","text":"to raise the water level to its upstream during the periods of low discharge in the parent channel"},{"key":"b","text":"to help in closing the supply to downstream of the parent channel"},{"key":"c","text":"to absorb fluctuations in various sections of the channel systems"},{"key":"d","text":"All of the above"}],"answer":"d","explanation":"A cross regulator heads up water for the off-takes during low supply and can shut off the supply downstream for repairs. It also absorbs fluctuations and helps control the whole system.","marks":1,"source":{"kind":"past","set":9,"question":27,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q27 · 1 mark"},"topic":"ACiE0705"},{"id":"PAST-09-031","src":"PAST-09-031","text":"The capacity of an irrigation channel is fixed based on","options":[{"key":"a","text":"cultivable command area and water transmission losses"},{"key":"b","text":"duty of water"},{"key":"c","text":"time factor"},{"key":"d","text":"all of the above"}],"answer":"d","explanation":"The head discharge is \\[Q = \\dfrac{\\text{CCA} \\times \\text{intensity}}{\\text{duty}}\\] corrected for the time factor and increased for transmission losses. All the listed factors enter the canal capacity.","marks":1,"source":{"kind":"past","set":9,"question":31,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q31 · 1 mark"},"topic":"ACiE0702"},{"id":"PAST-09-033","src":"PAST-09-033","text":"Which type of canal does not need cross drainage structures?","options":[{"key":"a","text":"Side slope canal"},{"key":"b","text":"Contour canal"},{"key":"c","text":"Watershed canal"},{"key":"d","text":"Both a and c"}],"answer":"d","explanation":"A watershed (ridge) canal runs along the ridge, and a side-slope canal runs roughly parallel to the natural drains, so neither crosses drainage. A contour canal cuts across the natural drains and needs cross-drainage works.","marks":1,"source":{"kind":"past","set":9,"question":33,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q33 · 1 mark"},"topic":"ACiE0702"},{"id":"PAST-09-048","src":"PAST-09-048","text":"Which of the following is the most efficient weir?","options":[{"key":"a","text":"Barrage"},{"key":"b","text":"Vertical drop"},{"key":"c","text":"Sloping"},{"key":"d","text":"Parabolic"}],"answer":"d","explanation":"A crest shaped to the lower nappe of a free jet (the ogee or parabolic profile) passes the most discharge for a given head, with a high discharge coefficient.","marks":1,"source":{"kind":"past","set":9,"question":48,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q48 · 1 mark"},"topic":"ACiE0703"},{"id":"PAST-09-050","src":"PAST-09-050","text":"Under which strata should tile drainage not be placed?","options":[{"key":"a","text":"In shallow depths"},{"key":"b","text":"More pervious strata"},{"key":"c","text":"Less pervious strata"},{"key":"d","text":"Pervious strata"}],"answer":"c","explanation":"Tile drains placed in or below a less pervious layer stay dry, because the water perched above the layer cannot reach them. They must lie in the pervious zone that holds the excess water.","marks":1,"source":{"kind":"past","set":9,"question":50,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q50 · 1 mark"},"topic":"ACiE0706"},{"id":"PAST-09-054","src":"PAST-09-054","text":"The design canal discharge is based on","options":[{"key":"a","text":"maximum Q of river"},{"key":"b","text":"maximum irrigation water requirement"},{"key":"c","text":"max crop water requirement"},{"key":"d","text":"empirical relationship"}],"answer":"b","explanation":"A canal is sized for the peak (maximum) irrigation requirement of its command during the crop calendar, including losses. The river's maximum flood is irrelevant to canal capacity.","marks":1,"source":{"kind":"past","set":9,"question":54,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q54 · 1 mark"},"topic":"ACiE0702"},{"id":"PAST-09-072","src":"PAST-09-072","text":"For the design of non-scouring channels in coarse alluviums, the Shields entrainment function should be","options":[{"key":"a","text":"\\(\\gt 0.056\\)"},{"key":"b","text":"\\(\\lt 0.056\\)"},{"key":"c","text":"\\(= 0.056\\)"},{"key":"d","text":"1"}],"answer":"b","explanation":"Shields' parameter τ<sub>0</sub>/[(γ<sub>s</sub>−γ)d] must stay below the critical value (about 0.056 for coarse, fully rough conditions) so that the bed grains do not move.","marks":2,"source":{"kind":"past","set":9,"question":72,"marks":2,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q72 · 2 marks"},"topic":"ACiE0702"},{"id":"PAST-09-074","src":"PAST-09-074","text":"The spacing of tile drains to relieve water-logged land is directly proportional to the","options":[{"key":"a","text":"depth of drain below the water level"},{"key":"b","text":"coefficient of permeability of the soil to be drained"},{"key":"c","text":"depth of drain below the ground surface"},{"key":"d","text":"depth of impervious strata from the drain"}],"answer":"b","explanation":"Drain-spacing formulas such as Hooghoudt's, \\[S^2 = \\dfrac{4K(b^2 - a^2)}{R}\\] make the spacing grow with the soil's permeability \\(K\\). More permeable soil allows wider spacing; the key takes \\(K\\) as the proportional factor.","marks":2,"source":{"kind":"past","set":9,"question":74,"marks":2,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q74 · 2 marks"},"topic":"ACiE0706"}]},{"name":"Hydropower","questions":[{"id":"PAST-09-044","src":"PAST-09-044","text":"What is the use of a governor (in a turbine)?","options":[{"key":"a","text":"It controls acceleration"},{"key":"b","text":"It controls the temperature"},{"key":"c","text":"It controls the mean speed"},{"key":"d","text":"It controls sediment"}],"answer":"c","explanation":"The governor adjusts the wicket gates or nozzle spear to the load, keeping the turbine's mean speed (and so the generator frequency) constant.","marks":1,"source":{"kind":"past","set":9,"question":44,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q44 · 1 mark"},"topic":"ACiE0806"},{"id":"PAST-09-045","src":"PAST-09-045","text":"Which one of the following methods of tunnelling is used in hard rocks?","options":[{"key":"a","text":"Fore poling method"},{"key":"b","text":"Needle beam method"},{"key":"c","text":"Heading and benching method"},{"key":"d","text":"Shield tunnelling method"}],"answer":"c","explanation":"Full-face, heading-and-bench and drift methods are used in hard rock. Forepoling, needle-beam and shield methods are soft-ground techniques.","marks":1,"source":{"kind":"past","set":9,"question":45,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q45 · 1 mark"},"topic":"ACiE0805"},{"id":"PAST-09-049","src":"PAST-09-049","text":"What is the dead storage of a storage reservoir?","options":[{"key":"a","text":"Level between bed level and full reservoir level"},{"key":"b","text":"Level between bed level and minimum pool level"},{"key":"c","text":"Level between bed level and max water level"},{"key":"d","text":"Level between minimum pool level and full reservoir level"}],"answer":"b","explanation":"Dead storage is the volume below the minimum pool (lowest outlet) level. It cannot be drawn and is kept for sediment. Useful storage lies between the minimum pool and full reservoir levels.","marks":1,"source":{"kind":"past","set":9,"question":49,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q49 · 1 mark"},"topic":"ACiE0803"},{"id":"PAST-09-075","src":"PAST-09-075","text":"A hydropower plant is going to be installed in Nepal with gross head (\\(H\\)) = 25 m, design flow (\\(Q\\)) = 0.7 m<sup>3</sup>/s and penstock length (\\(L\\)) = 500 m. If the flow velocity is 2 m/s, the effective diameter of the penstock pipe required is","options":[{"key":"a","text":"0.5 m"},{"key":"b","text":"0.87 m"},{"key":"c","text":"0.75 m"},{"key":"d","text":"0.667 m"}],"answer":"d","explanation":"The penstock diameter is \\[\\begin{aligned} D &amp;= \\sqrt{\\dfrac{4Q}{\\pi V}} = \\sqrt{\\dfrac{4 \\times 0.7}{\\pi \\times 2}} \\\\ &amp;= \\sqrt{0.446} \\approx 0.667\\ \\text{m} \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":9,"question":75,"marks":2,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q75 · 2 marks"},"topic":"ACiE0805"}]},{"name":"Transportation","questions":[{"id":"PAST-09-018","src":"PAST-09-018","text":"What is the maximum moisture content allowed in bitumen?","options":[{"key":"a","text":"0.1%"},{"key":"b","text":"0.2%"},{"key":"c","text":"1%"},{"key":"d","text":"2%"}],"answer":"b","explanation":"Paving bitumen should contain no more than about 0.2% water by weight, because water causes foaming when the bitumen is heated.","marks":1,"source":{"kind":"past","set":9,"question":18,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q18 · 1 mark"},"topic":"ACiE0903"},{"id":"PAST-09-020","src":"PAST-09-020","text":"Any gradient on a road is said to be an exceptional gradient if it is","options":[{"key":"a","text":"more than ruling gradient"},{"key":"b","text":"less than average gradient"},{"key":"c","text":"more than floating gradient"},{"key":"d","text":"less than minimum gradient or more than maximum gradient"}],"answer":"d","explanation":"Exceptional gradients are those outside the normal design range: steeper than the limiting (maximum) gradient or flatter than the minimum drainage gradient. They are allowed only over short lengths.","marks":1,"source":{"kind":"past","set":9,"question":20,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q20 · 1 mark"},"topic":"ACiE0902"},{"id":"PAST-09-021","src":"PAST-09-021","text":"What is the design speed for a 1st class road in plain terrain?","options":[{"key":"a","text":"80 kmph"},{"key":"b","text":"100 kmph"},{"key":"c","text":"110 kmph"},{"key":"d","text":"120 kmph"}],"answer":"d","explanation":"The Nepal Road Standard sets a design speed of about 120 km/h for class I roads in plain terrain, reduced in rolling, hilly and mountainous terrain.","marks":1,"source":{"kind":"past","set":9,"question":21,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q21 · 1 mark"},"topic":"ACiE0902"},{"id":"PAST-09-047","src":"PAST-09-047","text":"Pot hole maintenance in the case of a bituminous road is","options":[{"key":"a","text":"periodic maintenance"},{"key":"b","text":"recurrent maintenance"},{"key":"c","text":"special maintenance"},{"key":"d","text":"routine maintenance"}],"answer":"b","explanation":"In the DoR (Nepal) maintenance classes, pothole patching and crack sealing are recurrent maintenance: repairs needed at intervals through the year, depending on traffic and weather.","marks":1,"source":{"kind":"past","set":9,"question":47,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q47 · 1 mark"},"topic":"ACiE0906"},{"id":"PAST-09-056","src":"PAST-09-056","text":"Which intersection has no conflict?","options":[{"key":"a","text":"Clover leaf"},{"key":"b","text":"Diamond"},{"key":"c","text":"Channelized"},{"key":"d","text":"Trumpet"}],"answer":"a","explanation":"A full cloverleaf separates all through and turning movements by grades, loops and ramps, so no crossing conflicts remain. Diamond interchanges keep at-grade conflicts on the minor road.","marks":1,"source":{"kind":"past","set":9,"question":56,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q56 · 1 mark"},"topic":"ACiE0904"},{"id":"PAST-09-070","src":"PAST-09-070","text":"The superelevation formula in hilly roads is","options":[{"key":"a","text":"\\(e = \\dfrac{v^2}{127R}\\)"},{"key":"b","text":"\\(e = \\dfrac{v^2}{225R}\\)"},{"key":"c","text":"\\(e = \\dfrac{v^2}{30R}\\)"},{"key":"d","text":"\\(e = \\dfrac{v^2}{60R}\\)"}],"answer":"b","explanation":"For mixed traffic, IRC provides superelevation for 75% of the design speed, neglecting friction: \\[e = \\dfrac{(0.75v)^2}{127R} = \\dfrac{v^2}{225R}\\] It is limited to 10% on hill roads.","marks":2,"source":{"kind":"past","set":9,"question":70,"marks":2,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q70 · 2 marks"},"topic":"ACiE0902"}]},{"name":"Project Planning, Design and Implementation","questions":[{"id":"PAST-09-008","src":"PAST-09-008","text":"In which phase of the project are most of the money and manpower required?","options":[{"key":"a","text":"Initiation phase"},{"key":"b","text":"Planning phase"},{"key":"c","text":"Execution phase"},{"key":"d","text":"Closing phase"}],"answer":"c","explanation":"Most of the budget and workforce is spent during execution (implementation), when the actual construction or production takes place.","marks":1,"source":{"kind":"past","set":9,"question":8,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q8 · 1 mark"},"topic":"AALL1003"},{"id":"PAST-09-009","src":"PAST-09-009","text":"Which of the following is not a function of NEC?","options":[{"key":"a","text":"Prepare and implement the policy, plan and programmes"},{"key":"b","text":"Recognize the academic institutions"},{"key":"c","text":"Opening the college"},{"key":"d","text":"To prescribe the basic conditions of student admission"}],"answer":"c","explanation":"NEC frames policy, recognises engineering colleges and their programmes, and sets admission norms, but it does not open or run colleges.","marks":1,"source":{"kind":"past","set":9,"question":9,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q9 · 1 mark"},"topic":"AALL1006"},{"id":"PAST-09-022","src":"PAST-09-022","text":"A sinking fund is","options":[{"key":"a","text":"the fund for rebuilding a structure when its economic life is over"},{"key":"b","text":"raised to meet maintenance costs"},{"key":"c","text":"the total sum to be paid to the municipal authorities by the tenants"},{"key":"d","text":"a part of the money kept in reserve for providing additional structures and structural modifications"}],"answer":"a","explanation":"A sinking fund is built up by regular deposits (with interest) to replace or rebuild the property when its useful life ends.","marks":1,"source":{"kind":"past","set":9,"question":22,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q22 · 1 mark"},"topic":"AALL1002"},{"id":"PAST-09-024","src":"PAST-09-024","text":"Variability in the rate of return is known as","options":[{"key":"a","text":"return"},{"key":"b","text":"risk"},{"key":"c","text":"interest"},{"key":"d","text":"volatility"}],"answer":"b","explanation":"In finance, risk is the uncertainty or dispersion of actual returns about the expected return, usually measured by the standard deviation.","marks":1,"source":{"kind":"past","set":9,"question":24,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q24 · 1 mark"},"topic":"AALL1002"},{"id":"PAST-09-032","src":"PAST-09-032","text":"The Vice Chairman of NEC is","options":[{"key":"a","text":"nominated by GoN"},{"key":"b","text":"nominated by NEC"},{"key":"c","text":"elected"},{"key":"d","text":"selected through open competition"}],"answer":"a","explanation":"Under the NEC Act, the Government of Nepal nominates the vice-chairperson (an engineer with at least ten years' experience after a bachelor's degree), as it does the chairperson.","marks":1,"source":{"kind":"past","set":9,"question":32,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q32 · 1 mark"},"topic":"AALL1006"},{"id":"PAST-09-037","src":"PAST-09-037","text":"What is the inclination of inclined lettering?","options":[{"key":"a","text":"75 degree"},{"key":"b","text":"65 degree"},{"key":"c","text":"45 degree"},{"key":"d","text":"85 degree"}],"answer":"a","explanation":"Inclined (sloping) letters are drawn at 75° to the horizontal.","marks":1,"source":{"kind":"past","set":9,"question":37,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q37 · 1 mark"},"topic":"AALL1001"},{"id":"PAST-09-039","src":"PAST-09-039","text":"Resource smoothing is","options":[{"key":"a","text":"an optimization and economical utilization of resources"},{"key":"b","text":"an adjustment of resources without affecting project duration"},{"key":"c","text":"a gradual increase in resources"},{"key":"d","text":"a gradual decrease in resources"}],"answer":"b","explanation":"In resource smoothing the project duration is fixed. Activities are shifted within their floats to even out the peaks and valleys of resource demand.","marks":1,"source":{"kind":"past","set":9,"question":39,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q39 · 1 mark"},"topic":"AALL1003"},{"id":"PAST-09-059","src":"PAST-09-059","text":"The number of professional engineers registered by the time 2078/12/31 is","options":[{"key":"a","text":"71"},{"key":"b","text":"61"},{"key":"c","text":"51"},{"key":"d","text":"41"}],"answer":"b","explanation":"NEC's records give 61 professional engineers registered by 2078-12-31 (BS). This is a record-based fact from the source key.","marks":1,"source":{"kind":"past","set":9,"question":59,"marks":1,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q59 · 1 mark"},"topic":"AALL1006"},{"id":"PAST-09-068","src":"PAST-09-068","text":"What is the definition of mitigation in the context of risk management?","options":[{"key":"a","text":"The process of identifying and assessing potential risks"},{"key":"b","text":"The complete elimination of all risks within a system"},{"key":"c","text":"The implementation of strategies to reduce the impact or likelihood of identified risks"},{"key":"d","text":"The transfer of risks to external parties through insurance"}],"answer":"c","explanation":"Mitigation means acting to reduce the probability or the consequences of identified risks. Identification is assessment, and insurance is risk transfer.","marks":2,"source":{"kind":"past","set":9,"question":68,"marks":2,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q68 · 2 marks"},"topic":"AALL1004"},{"id":"PAST-09-069","src":"PAST-09-069","text":"What type of sketch shows the front in true shape?","options":[{"key":"a","text":"Isometric"},{"key":"b","text":"Perspective"},{"key":"c","text":"Oblique"},{"key":"d","text":"Axonometric"}],"answer":"c","explanation":"An oblique drawing places the front face parallel to the picture plane, so it appears in true shape and size, with the receding lines drawn at an angle.","marks":2,"source":{"kind":"past","set":9,"question":69,"marks":2,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q69 · 2 marks"},"topic":"AALL1001"},{"id":"PAST-09-079","src":"PAST-09-079","text":"How much % should a college score at least to get affiliation from NEC?","options":[{"key":"a","text":"50%"},{"key":"b","text":"60%"},{"key":"c","text":"70%"},{"key":"d","text":"80%"}],"answer":"c","explanation":"Per the source key, an engineering college needs at least 70% in NEC's evaluation to be recognised (affiliated).","marks":2,"source":{"kind":"past","set":9,"question":79,"marks":2,"date":"2080 Mangsir 22","shift":"1st shift","reference":"Past Paper Set 9, Q79 · 2 marks"},"topic":"AALL1006"}]}]};
